def _1769_module_xml(catalog: str, major_rev: str) -> str:
    """The real per-catalog <Modules> block (see _1769_MODULES_XML above),
    with only the Local module's own Major/Minor substituted to match the
    target firmware version -- exactly one occurrence per real reference
    file (verified), matching how every other catalog in this matrix has
    its Local module's Major/Minor track the Controller's own MajorRev.
    The rest (Ports, embedded Discrete_IO module and its real Connection/
    ConfigTag content, EKey) is untouched, real, verbatim."""
    block = _1769_MODULES_XML[catalog]
    old = f'CatalogNumber="{catalog}" Vendor="1" ProductType="14" ProductCode="{_PRODUCT_CODES[catalog]}" Major="35" Minor="11"'
    new = f'CatalogNumber="{catalog}" Vendor="1" ProductType="14" ProductCode="{_PRODUCT_CODES[catalog]}" Major="{major_rev}" Minor="11"'
    assert block.count(old) == 1, f"expected exactly 1 Local-module Major substitution site for {catalog!r}, found {block.count(old)}"
    return block.replace(old, new)

# GuardLogix 5580 safety-rated (James, 2026-08-25: "L8 needs safety
# processors too"). REAL BUG FOUND AND FIXED 2026-08-30 (James: "this file
# fails to convert to acd" on fwmatrix_v35_1756_l85es -- direct real-world
# proof, not a code-review catch): the "L81ES uses the SAME ProductCode as
# plain L81E" assumption below was never actually checked against a real
# L81ES corpus file -- it was a same-hardware plausibility argument, not
# data. Real corpus grep (5 independent real files: SJ_Gormley_20251112_r02,
# Bender134053_201104 x2 copies, RobbinsGrn_2026_05_13r00,
# FlareFunction_311D_240731) shows GuardLogix 5580 ProductCodes live in a
# COMPLETELY SEPARATE numbering space from the non-safety L8x: L81ES=211
# (4 real files agree) and L84ES=214 (1 real file, FlareFunction_311D --
# never found by this project until now). 211->214 across L81ES->L84ES is
# exactly +1 per catalog step, the same sequential pattern this project
# already uses elsewhere for an unconfirmed run -- L82ES(212)/L83ES(213)
# have both since been real-tested by James (import succeeds, no line-1
# error) though still not independently confirmed as the exact real
# ProductCode the way L81ES/L84ES are.
#
# L85ES(215) REMOVED 2026-08-30 (James: "l85es fails on line 1 of the l5x
# for multiple firmwares but works fine for l81es..l84es"): the same
# +1-per-step inference that correctly predicted L82ES/L83ES broke
# specifically at the L84ES->L85ES step -- real proof the sequence isn't
# linear all the way to the top of the range (1756-L85ES IS a real,
# current Rockwell product -- 40MB/3MB safety memory, confirmed via web
# search -- so this isn't a fake-catalog problem, just an unconfirmed
# ProductCode with no more real anchor to re-derive it from). Rather than
# guess again and burn another of James's test cycles, treated the same
# as OQ-BASELINE-PROCFW already treats 1756-L9x: sourced but deliberately
# NOT generated until a real L85ES sample (or its real ProductCode)
# surfaces. See docs/OPEN_QUESTIONS.md.
_L8XS_PRODUCT_CODES = {
    "1756-L81ES": "211",
    "1756-L82ES": "212",
    "1756-L83ES": "213",
    "1756-L84ES": "214",
}
_L8XS_INFERRED = {"1756-L82ES", "1756-L83ES"}
_L8XS_CATALOGS = list(_L8XS_PRODUCT_CODES)

ALL_CATALOGS = _L8X_CATALOGS + _5069_CATALOGS + _L7X_CATALOGS + _1769_CATALOGS
SAFETY_CATALOGS = _L8XS_CATALOGS
ALL_INFERRED = _L7X_INFERRED | _L8XS_INFERRED


def _product_code(catalog: str) -> str:
    if catalog in _PRODUCT_CODES:
        return _PRODUCT_CODES[catalog]
    if catalog in _5069_EXTRA_PRODUCT_CODES:
        return _5069_EXTRA_PRODUCT_CODES[catalog]
    if catalog in _L7X_PRODUCT_CODES:
        return _L7X_PRODUCT_CODES[catalog]
    if catalog in _L8XS_PRODUCT_CODES:
        return _L8XS_PRODUCT_CODES[catalog]
    raise KeyError(f"No confirmed real ProductCode for {catalog!r} -- refusing to guess")


def _local_ports_xml(catalog: str, is_safety: bool = False) -> str:
    if is_safety:
        # REAL BUG FOUND 2026-08-30 (James: "your L8 safety failed to
        # generate acd files" -- watched the conversion fail directly).
        # A Safety-capable CPU's own Local module Ports need a
        # SafetyNetwork attribute on EVERY port, not just the Task/Program
        # Class="Safety" markers this generator already had. Confirmed
        # against samples/local/SJ_Gormley_20251112_r02.L5X, whose
        # Controller CatalogNumber is literally "1756-L81ES" -- the exact
        # family reported failing -- real Local module: both Port 1 (ICP)
        # and Port 2 (Ethernet) carry SafetyNetwork. This generator never
        # added it at all for the L8xES catalogs (SAFETY_CATALOGS), a
        # completely separate code path from wrapper.py's build_l5x,
        # which already got the analogous SIL2/SIL3 module-sweep fix
        # 2026-08-28 and was never cross-applied here. Real SafetyNetwork
        # values are device-unique (confirmed real corpus values are
        # effectively random 64-bit hex, not sequential) -- this project
        # has no way to fabricate a "real" one, so uses the same
        # synthetic-but-correctly-formatted placeholder convention
        # wrapper.py already established, one distinct value per port.
        return (
            f'<Port Id="1" Address="0" Type="ICP" Upstream="false" '
            f'SafetyNetwork="16#0000_1005_0001_0001">\n'
            f'<Bus Size="{_ICP_BUS_SIZE}"/>\n'
            f'</Port>\n'
            f'<Port Id="2" Type="Ethernet" Upstream="false" '
            f'SafetyNetwork="16#0000_1005_0002_0002">\n<Bus/>\n</Port>'
        )
    if catalog.startswith("5069"):
        return (
            f'<Port Id="1" Address="0" Type="5069" Upstream="false">\n'
            f'<Bus Size="{_5069_bus_size(catalog)}"/>\n'
            f'</Port>\n'
            f'<Port Id="3" Type="Ethernet" Upstream="false">\n<Bus/>\n</Port>\n'
            f'<Port Id="4" Type="Ethernet" Upstream="false">\n<Bus/>\n</Port>'
        )
    if catalog in _L7X_PRODUCT_CODES:
        # REAL BUG FOUND 2026-08-28 (James sent a fresh real Studio 5000
        # export of 1756-L71 for comparison; the exact same shape was
        # ALSO already sitting unused in samples/local/L7_v21_Sample.L5X
        # -- this generator was never cross-checked against it).
        # ControlLogix 5570 (1756-L7x) has NO embedded Ethernet port on
        # the CPU module itself -- Ethernet comes from a separate bridge
        # module in another slot, unlike 1756-L8x's embedded port. Real
        # shape: exactly ONE Port (ICP, Bus Size=4, not the L8x-style 17),
        # no second Port element at all. The caller must also skip the
        # top-level <EthernetPorts> element for this family -- see
        # _build_xml. Only L71 is directly corpus-confirmed; L72-L75 are
        # the same physical ControlLogix 5570 form factor so treated the
        # same, not independently confirmed per-catalog.
        return f'<Port Id="1" Address="0" Type="ICP" Upstream="false">\n<Bus Size="4"/>\n</Port>'
    if catalog.startswith("1769"):
        # CompactLogix 5370 real shape, same source/derivation as wrapper.
        # py's _1769_bus_size (samples/local/DnR_Personal/TOYOTA_135453_
        # 20221024.L5X, ProcessorType="1769-L33ERMS"): Port Type="Compact"
        # (distinct from both 1756's "ICP" and 5069's "5069"), single
        # Ethernet port -- same single-Ethernet shape as 1756/L7x, unlike
        # 5069's dual-Ethernet. Only L33 has a confirmed real bus size
        # (17); every other 1769 catalog falls back to that same value,
        # unconfirmed for its own model specifically.
        return (
            f'<Port Id="1" Address="0" Type="Compact" Upstream="false">\n'
            f'<Bus Size="{_1769_bus_size(catalog)}"/>\n'
            f'</Port>\n'
            f'<Port Id="2" Type="Ethernet" Upstream="false">\n<Bus/>\n</Port>'
        )
    return (
        f'<Port Id="1" Address="0" Type="ICP" Upstream="false">\n'
        f'<Bus Size="{_ICP_BUS_SIZE}"/>\n'
        f'</Port>\n'
        f'<Port Id="2" Type="Ethernet" Upstream="false">\n<Bus/>\n</Port>'
    )


def _build_xml(catalog: str, major_rev: str, software_revision: str, extra_attrs: str,
                is_safety: bool = False) -> str:
    target_name = f"FwMatrix{major_rev}" + "".join(c for c in catalog if c.isalnum())
    now = datetime.now().strftime("%a %b %d %H:%M:%S %Y")
    if "{DATAEXCHANGEID}" in extra_attrs:
        guid = "{" + str(uuid.uuid4()).upper() + "}"
        extra_attrs = extra_attrs.replace("{DATAEXCHANGEID}", guid)
    product_code = _product_code(catalog)
    local_ports_xml = _local_ports_xml(catalog, is_safety=is_safety)
    # Real shape confirmed 2026-08-25 against samples/local/SJ_Gormley_
    # 20251112_r02.L5X and DnR_Personal/Bender134053_201104.L5X (James:
    # "Safety processor needs a safety task. You don't have to put in a
    # safety program... check Gormley or bender as samples"): the real
    # marker isn't the NAME "SafetyTask" -- it's Class="Safety" on BOTH
    # the Task and the Program it schedules. Kept minimal (bare
    # MainRoutine, no real safety content) per James's "don't have to put
    # in a safety program" -- but a Task always schedules a real Program
    # in both real references, so the pairing itself is kept, just empty.
    # REAL BUG FOUND 2026-08-30 (James: "your L8 safety failed to generate
    # acd files. You should have known that"). SafetyLocked="true" with no
    # SafetySignature attribute is an invalid combination -- checked all
    # 9 real corpus files with a SafetyInfo element: every one of the 4
    # with SafetyLocked="true" ALSO carries a real SafetySignature (a GUID
    # hash + timestamp, generated by Studio 5000's actual sign/lock
    # workflow); every one of the 5 with SafetyLocked="false" has none.
    # This generator hardcoded locked=true with no signature at all --
    # zero real files ever show that combination. Since the safety program
    # here is deliberately minimal (a bare NOP, no real signing performed),
    # the correct real value is SafetyLocked="false", matching every real
    # file that similarly has no signature.
    safety_info_xml = '<SafetyInfo SafetyLocked="false" SignatureRunModeProtect="false" ConfigureSafetyIOAlways="true" SafetyLevel="SIL2/PLd"/>' if is_safety else '<SafetyInfo/>'
    safety_program_xml = (
        '<Program Name="SafetyProgram" TestEdits="false" MainRoutineName="MainRoutine" '
        'Disabled="false" Class="Safety" UseAsFolder="false">\n<Tags/>\n<Routines>\n'
        '<Routine Name="MainRoutine" Type="RLL">\n<RLLContent>\n'
        '<Rung Number="0" Type="N"><Text><![CDATA[NOP();]]></Text></Rung>\n'
        '</RLLContent>\n</Routine>\n</Routines>\n</Program>\n'
    ) if is_safety else ""
    safety_task_xml = (
        '<Task Name="SafetyTask" Type="PERIODIC" Rate="20" Priority="10" Watchdog="20" '
        'DisableUpdateOutputs="false" InhibitTask="false" Class="Safety">\n<ScheduledPrograms>\n'
        '<ScheduledProgram Name="SafetyProgram"/>\n</ScheduledPrograms>\n</Task>\n'
    ) if is_safety else ""
    # Real attributes confirmed 2026-08-28 -- were sitting unused in
    # samples/local/L7_v21_Sample.L5X AND a fresh export James sent for
    # direct comparison, both showing the exact same shape. Added for
    # fidelity; build_l5x's own template omits both and still imports
    # fine across ~1300 already-tested files, so these are almost
    # certainly Studio-5000-optional (internal defaults applied when
    # absent) rather than the actual cause of any real failure -- but now
    # that real values exist, there's no reason to keep omitting them.
    time_slice_attrs = ' TimeSlice="20" ShareUnusedTimeSlice="1"'
    redundancy_pad_attrs = ' IOMemoryPadPercentage="90" DataTablePadPercentage="50"'
    # REAL BUG FOUND 2026-08-28: ControlLogix 5570 (1756-L7x) has no
    # embedded Ethernet interface on the CPU module -- see
    # _local_ports_xml's docstring above. The top-level <EthernetPorts>
    # element describes THAT embedded interface, so it must be omitted
    # entirely for this family too, not just the Local module's second
    # Port -- confirmed absent in both real L71 references.
    if catalog in _L7X_PRODUCT_CODES:
        ethernet_ports_xml = ""
    elif catalog.startswith("1769"):
        ethernet_ports_xml = _1769_ETHERNET_XML
    else:
        ethernet_ports_xml = '<EthernetPorts>\n<EthernetPort Port="1" Label="1" PortEnabled="true"/>\n</EthernetPorts>\n'
    # REAL BUG FOUND 2026-08-28 (James: "looks like your 5069-LxxERMSx
    # has issues as well"). EtherNetIPMode="A1/A2: Dual-IP" is a real
    # Controller-level attribute confirmed present, identical value, in
    # EVERY 5069 corpus file checked (6/6, zero variance) -- a
    # 5069-family-wide gap (describes the CPU's two embedded Ethernet
    # ports' addressing mode), not specific to the ERMSx subset James
    # happened to be testing. See wrapper.py's build_l5x for the same fix.
    ethernet_ip_mode_attr = ' EtherNetIPMode="A1/A2: Dual-IP"' if catalog.startswith("5069") else ""
    # 1769 (CompactLogix 5370) uses the real, verbatim per-catalog Modules
    # block (embedded Discrete_IO and all) instead of the generic single-
    # Local-module template every other family uses -- see
    # _1769_module_xml's docstring.
    if catalog.startswith("1769"):
        modules_xml = _1769_module_xml(catalog, major_rev)
    else:
        modules_xml = (
            f'<Modules>\n'
            f'<Module Name="Local" CatalogNumber="{catalog}" Vendor="1" ProductType="14" ProductCode="{product_code}" '
            f'Major="{major_rev}" Minor="{MINOR_REV}" ParentModule="Local" ParentModPortId="1" Inhibited="false" MajorFault="true">\n'
            f'<EKey State="Disabled"/>\n'
            f'<Ports>\n'
            f'{local_ports_xml}\n'
            f'</Ports>\n'
            f'</Module>\n'
            f'</Modules>'
        )
    return f"""<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<RSLogix5000Content SchemaRevision="1.0" SoftwareRevision="{software_revision}" TargetName="{target_name}" TargetType="Controller" ContainsContext="false" Owner="Admin" ExportDate="{now}" ExportOptions="NoRawData L5KData DecoratedData ForceProtectedEncoding AllProjDocTrans">
<Controller Use="Target" Name="{target_name}" ProcessorType="{catalog}" MajorRev="{major_rev}" MinorRev="{MINOR_REV}"{time_slice_attrs} ProjectCreationDate="{now}" LastModifiedDate="{now}" SFCExecutionControl="CurrentActive" SFCRestartPosition="MostRecent" SFCLastScan="DontScan" ProjectSN="16#0000_0000" MatchProjectToController="false" CanUseRPIFromProducer="false" InhibitAutomaticFirmwareUpdate="0" PassThroughConfiguration="EnabledWithAppend" DownloadProjectDocumentationAndExtendedProperties="true" DownloadProjectCustomProperties="true" ReportMinorOverflow="false"{ethernet_ip_mode_attr}{extra_attrs}>
<RedundancyInfo Enabled="false" KeepTestEditsOnSwitchOver="false"{redundancy_pad_attrs}/>
<Security Code="0" ChangesToDetect="16#ffff_ffff_ffff_ffff"/>
{safety_info_xml}
<DataTypes/>
{modules_xml}
<AddOnInstructionDefinitions/>
<Tags/>
<Programs>
<Program Name="MainProgram" TestEdits="false" MainRoutineName="MainRoutine" Disabled="false" UseAsFolder="false">
<Tags/>
<Routines>
<Routine Name="MainRoutine" Type="RLL">
<RLLContent>
<Rung Number="0" Type="N"><Text><![CDATA[NOP();]]></Text></Rung>
</RLLContent>
</Routine>
</Routines>
</Program>
{safety_program_xml}</Programs>
<Tasks>
<Task Name="MainTask" Type="CONTINUOUS" Priority="10" Watchdog="500" DisableUpdateOutputs="false" InhibitTask="false">
<ScheduledPrograms>
<ScheduledProgram Name="MainProgram"/>
</ScheduledPrograms>
</Task>
{safety_task_xml}</Tasks>
<CST MasterID="0"/>
<WallClockTime LocalTimeAdjustment="0" TimeZone="0"/>
<Trends/>
<DataLogs/>
<TimeSynchronize Priority1="128" Priority2="128" PTPEnable="false"/>
{ethernet_ports_xml}</Controller>
</RSLogix5000Content>
"""


def _write(l5x: str, out_name: str, description: str) -> None:
    out_path = OUT_ROOT / f"{out_name}.L5X"
    try:
        bytes_ = write_sample(l5x, out_path)
    except RuntimeError as exc:
        # Real 1769 "ER"/"ERM" catalogs (L16ER through L27ERM-QBFC1B) carry
        # a genuine embedded Discrete_IO module (CatalogNumber="Embedded")
        # -- the sizing engine already deliberately leaves processor-
        # embedded I/O unmodeled (2026-08-27, same real corpus, OQ-
        # BASELINE-PROCFW: "zero real data confirms an embedded processor-
        # integrated I/O block costs the same [as a discrete add-on
        # module]"), which surfaces here as a SizeError rather than a real
        # bug. Same write_sample_unmodeled/predicted_bytes=0 convention
        # already used for this exact real corpus elsewhere in the project.
        if "Embedded" not in str(exc):
            raise
        write_sample_unmodeled(l5x, out_path)
        bytes_ = 0
    append_manifest_row(out_name, description, "fw_catalog_matrix", out_path, bytes_)


def main() -> None:
    written = 0
    all_catalogs = ALL_CATALOGS + SAFETY_CATALOGS
    for major_rev, software_revision, extra_attrs, assumed in FIRMWARE_TABLE:
        for catalog in all_catalogs:
            is_safety = catalog in SAFETY_CATALOGS
            slug = catalog.lower().replace("-", "_")
            out_name = f"fwmatrix_v{major_rev}_{slug}"
            assumed_note = (
                f" ASSUMED firmware-attribute shape (no real v{major_rev} sample exists yet -- "
                f"interpolated from the confirmed v35/v38 bracket, correct from real capture)."
                if assumed else ""
            )
            inferred_note = (
                f" ProductCode {_product_code(catalog)} is INFERRED (same-tier sequential pattern "
                f"from confirmed neighbors), not independently confirmed for this exact catalog."
                if catalog in ALL_INFERRED else ""
            )
            safety_note = (
                " GuardLogix safety-rated (SIL2/PLd, single primary, no partner) -- real Task/"
                "Program Class=\"Safety\" shape confirmed against Gormley/Bender real corpus."
                if is_safety else ""
            )
            l5x = _build_xml(catalog, major_rev, software_revision, extra_attrs, is_safety=is_safety)
            _write(
                l5x, out_name,
                f"Blank baseline, {catalog} at firmware {major_rev} (SoftwareRevision "
                f"{software_revision}) -- OQ-BASELINE-PROCFW full catalog x firmware matrix."
                f"{assumed_note}{inferred_note}{safety_note}",
            )
            written += 1
    print(f"Done. {written} files ({len(FIRMWARE_TABLE)} firmware versions x {len(all_catalogs)} catalogs).")


if __name__ == "__main__":
    main()
